138	func (s *APIV1Service) BatchGetUsers(ctx context.Context, request *v1pb.BatchGetUsersRequest) (*v1pb.BatchGetUsersResponse, error) {
139		if len(request.Usernames) == 0 {
140			return &v1pb.BatchGetUsersResponse{Users: []*v1pb.User{}}, nil
141		}
142	
143		uniqueUsernames, nonEmptyUsernameCount := normalizeBatchUsernames(request.Usernames)
144		if nonEmptyUsernameCount > maxBatchGetUsers {
145			return nil, status.Errorf(codes.InvalidArgument, "too many usernames (max %d)", maxBatchGetUsers)
146		}
147	
148		if len(uniqueUsernames) == 0 {
149			return &v1pb.BatchGetUsersResponse{Users: []*v1pb.User{}}, nil
150		}
151	
152		normal := store.Normal
153		users, err := s.Store.ListUsers(ctx, &store.FindUser{
154			UsernameList: uniqueUsernames,
155			RowStatus:    &normal,
156		})
157		if err != nil {
158			return nil, status.Errorf(codes.Internal, "failed to list users: %v", err)
159		}
160	
161		currentUser, _ := s.fetchCurrentUser(ctx)
162		response := &v1pb.BatchGetUsersResponse{
163			Users: make([]*v1pb.User, 0, len(users)),
164		}
165		for _, user := range users {
166			response.Users = append(response.Users, convertUserFromStore(user, currentUser))
167		}
168		return response, nil
169	}
